inputThis:
$:set -euo pipefail
test -f AGENTS.md
if test -f README.md; then cat README.md >/dev/null; fi
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
test ! -e .devcontainer/devcontainer.json
test ! -e config/file-metadata.json
mkdir -p .devcontainer
cat > .devcontainer/devcontainer.json <<'DEVCONTAINER_EOF'
{
  "name": "Terminals MCP Development",
  "image": "mcr.microsoft.com/devcontainers/javascript-node:1-22-bookworm",
  "features": {
    "ghcr.io/devcontainers/features/github-cli:1": {}
  },
  "forwardPorts": [
    3000
  ],
  "portsAttributes": {
    "3000": {
      "label": "MCP development server",
      "onAutoForward": "notify",
      "visibility": "private"
    }
  },
  "customizations": {
    "vscode": {
      "extensions": [
        "dbaeumer.vscode-eslint"
      ]
    }
  },
  "remoteUser": "node"
}
DEVCONTAINER_EOF
node -e 'const fs=require("fs");const p=".devcontainer/devcontainer.json";const c=JSON.parse(fs.readFileSync(p,"utf8"));if(c.image!=="mcr.microsoft.com/devcontainers/javascript-node:1-22-bookworm")process.exit(2);console.log("VALIDATED",p,fs.statSync(p).size)'
git add -- .devcontainer/devcontainer.json
git diff --cached --check
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git commit -m 'Add Node.js Codespaces devcontainer for MCP development'
for i in 1 2 3 4; do
 git fetch origin main -q
 git rebase origin/main -q
 if git push origin HEAD:main; then break; fi
 test "$i" -lt 4
done
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
git show --stat --oneline HEAD
